from flask import Flask, request, jsonify
import os, requests
app = Flask(__name__)
LOCAL_READY = True
def check_capacity():
    # very simple capacity check read from file or toggled in UI
    return LOCAL_READY
@app.route('/infer', methods=['POST'])
def infer():
    payload = request.json
    if check_capacity():
        r = requests.post('http://dedicated:8081/infer', json=payload, timeout=2.0)
    else:
        r = requests.post('https://api.redwood.com/v1/generate', json=payload, headers={'Authorization': f'Bearer {os.getenv("REDWOOD_API_KEY")}'}, timeout=6.0)
    return (r.text, r.status_code, r.headers.items())
